const requestedRoute=location.hash.slice(1);
const $=s=>document.querySelector(s);let selected=null,layer='health',scenario='normal';
const base=Array.from({length:48},(_,i)=>{const row=Math.floor(i/8),col=i%8;return {id:String.fromCharCode(65+row)+(col+1),station:'АС–'+String(Math.floor(row/2)*4+Math.floor(col/2)+1).padStart(2,'0'),moisture:Math.round(25+Math.sin(i*1.7)*5-((col>5&&row<3)?12:0)+((col<2&&row>3)?10:0)),temp:Math.round((19+Math.cos(i*.8)*3+((col>5&&row<3)?6:0))*10)/10,air:Math.round((23+Math.sin(i*.5)*2)*10)/10,humidity:Math.round(58+Math.cos(i)*9),battery:Math.round(74+Math.sin(i*.6)*22)}});
function data(){return base.map(x=>({...x,moisture:Math.max(5,x.moisture+(scenario==='dry'?-7:scenario==='rain'?12:0)),temp:+(x.temp+(scenario==='dry'?5:scenario==='rain'?-3:0)).toFixed(1)}))}
function risk(x){return x.moisture<16||x.moisture>42||x.temp>30?2:x.moisture<22||x.moisture>34||x.temp>26?1:0}
function tone(x){let r=layer==='battery'?(x.battery<60?2:x.battery<75?1:0):layer==='temp'?(x.temp>30?2:x.temp>26?1:0):layer==='moisture'?(x.moisture<16||x.moisture>42?2:x.moisture<22||x.moisture>34?1:0):risk(x);return ['#65956c','#c6a85d','#c77760'][r]}
function avg(key){return data().reduce((s,x)=>s+x[key],0)/48}function current(){return selected?data().find(x=>x.id===selected):{moisture:avg('moisture'),temp:avg('temp'),air:avg('air'),humidity:avg('humidity')}}
function num(v){return v.toLocaleString('ru-RU',{maximumFractionDigits:1})}
function openCell(id){selected=id;render();switchTab('monitor')}
function switchTab(id){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===id));if(id!=='monitor')window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));
function adviceFor(x){if(x.moisture<22)return {title:'Недостаток влаги',reason:`Влажность почвы ${num(x.moisture)}% — ниже условного диапазона 22–34%.`,action:'Проверить влажность контрольным замером и состояние растений. Оценить потребность в поливе с агрономом.'};if(x.moisture>34)return {title:'Повышенная влажность',reason:`Влажность почвы ${num(x.moisture)}% — выше условного диапазона.`,action:'Осмотреть участок на застой воды, проверить дренаж и показания датчика. Не назначать полив автоматически.'};if(x.temp>26)return {title:'Нагрев почвы',reason:`Температура почвы ${num(x.temp)} °C — выше демонстрационного порога.`,action:'Сопоставить показания с погодой, фазой развития растений и контрольным замером.'};return {title:'Стабильные условия',reason:'Показатели в пределах условных порогов демосценария.',action:'Продолжать наблюдения. Нормальные показатели датчиков не исключают других проблем растений.'}}
