function render(){const d=data(),c=current();$('#grid').innerHTML=d.map(x=>`<button class="cell ${x.id===selected?'selected':''}" style="--cell-color:${tone(x)}" data-id="${x.id}" title="${x.id}: влага ${x.moisture}%, почва ${x.temp}°C" aria-label="Ячейка ${x.id}, влажность ${x.moisture} процентов" aria-pressed="${x.id===selected}">${x.id}<small>${layer==='temp'?num(x.temp)+'°':layer==='battery'?x.battery+'%':x.moisture+'%'}</small></button>`).join('');$('#grid').querySelectorAll('button').forEach(b=>b.onclick=()=>openCell(b.dataset.id));$('#metricTitle').textContent=selected?'Участок '+selected:'Средние показатели поля';$('#selectionNote').textContent=selected?d.find(x=>x.id===selected).station+' · модельные значения':'48 ячеек · 12 виртуальных станций';$('#maptitle').textContent=selected?'Выбран участок '+selected:'Карта состояния поля';$('#mapsummary').textContent=`${d.filter(x=>!risk(x)).length} в норме / ${alerts().length} требуют внимания`;$('#alertCount').textContent=alerts().length;
const metrics=[['Влажность почвы',c.moisture,'%','Условный ориентир: 22–34%',c.moisture<22||c.moisture>34],['Температура почвы',c.temp,'°C','Порог внимания в демо: 26 °C',c.temp>26],['Температура воздуха',c.air,'°C','Микроклимат на участке',false],['Влажность воздуха',c.humidity,'%','Контекст для анализа',false]];$('#metrics').innerHTML=metrics.map(([t,v,u,h,w])=>`<div class="metric"><span>${t}</span><strong>${num(v)} <em>${u}</em></strong><small class="${w?'warn':'ok'}">${w?'↗':'●'} ${h}</small></div>`).join('');
let list=selected?[d.find(x=>x.id===selected)]:alerts().slice(0,2);if(!list.length)list=[d[0]];$('#advice').innerHTML=list.map(x=>{const a=adviceFor(x);return `<div class="alert"><strong>${x.id} · ${a.title}</strong><p>${a.reason}</p><button data-cell="${x.id}">Открыть участок →</button></div>`}).join('');$('#advice').querySelectorAll('button').forEach(b=>b.onclick=()=>openCell(b.dataset.cell));$('#adviceTitle').textContent=selected?'Рекомендация для '+selected:'На что посмотреть';
$('#insightList').innerHTML=(alerts().length?alerts():[d[0]]).map(x=>{const a=adviceFor(x);return `<button class="insight" data-cell="${x.id}"><span class="pill">${risk(x)===2?'Высокий приоритет':'Наблюдение'} · ${x.id}</span><h2>${a.title}</h2><p>${a.reason}</p><strong>Следующий шаг</strong><p>${a.action}</p><span>Открыть на карте ↗</span></button>`}).join('');$('#insightList').querySelectorAll('button').forEach(b=>b.onclick=()=>openCell(b.dataset.cell));renderTable();drawChart();}
function renderTable(){const q=$('#search').value.toLowerCase();$('#dataRows').innerHTML=data().filter(x=>(x.id+' '+x.station).toLowerCase().includes(q)).map(x=>`<tr><td>${x.id}</td><td>${x.station}</td><td>${x.moisture}</td><td>${num(x.temp)}</td><td>${num(x.air)}</td><td>${x.humidity}</td><td>Синтетический</td></tr>`).join('')}
function drawChart(){const key=$('#forecastMetric').value,v=current()[key],dry=scenario==='dry',rain=scenario==='rain',delta=key==='moisture'?(dry?-1.2:rain?.3:-.45):(dry?.55:rain?-.25:.1);let vals=Array.from({length:15},(_,i)=>i<=7?v+Math.sin(i*1.2)*1.3+(7-i)*.15:v+(i-7)*delta);let min=Math.floor((Math.min(...vals)-4)/5)*5,max=Math.ceil((Math.max(...vals)+4)/5)*5;let X=i=>42+i*37,Y=v=>166-(v-min)/(max-min)*135;let path=(a,b)=>vals.slice(a,b+1).map((v,j)=>(j?'L':'M')+X(a+j)+','+Y(v)).join(' ');let band=vals.slice(7).map((v,j)=>X(j+7)+','+Y(v+1.2+j*.18)).concat(vals.slice(7).map((v,j)=>X(j+7)+','+Y(v-1.2-j*.18)).reverse()).join(' ');$('#chart').innerHTML=`<svg viewBox="0 0 600 200" role="img" aria-label="История и условный семидневный прогноз ${key==='moisture'?'влажности почвы':'температуры почвы'}">${Array.from({length:4},(_,i)=>{let n=min+(max-min)*i/3;return `<line x1="42" y1="${Y(n)}" x2="560" y2="${Y(n)}" stroke="#e9ede3"/><text x="31" y="${Y(n)+3}" text-anchor="end" font-size="9" fill="#8d9b83">${Math.round(n)}</text>`}).join('')}<rect x="301" y="20" width="259" height="146" fill="#eaf1dd" opacity=".45"/><polygon points="${band}" fill="#bad292" opacity=".4"/><path d="${path(0,7)}" fill="none" stroke="#4c784e" stroke-width="2.5"/><path d="${path(7,14)}" fill="none" stroke="#719450" stroke-width="2.5" stroke-dasharray="5 5"/><line x1="301" y1="20" x2="301" y2="170" stroke="#9bb67d" stroke-dasharray="3 4"/><circle cx="301" cy="${Y(v)}" r="5" fill="#426a3c" stroke="white" stroke-width="2"/>${[0,3,7,10,14].map(i=>`<text x="${X(i)}" y="188" text-anchor="middle" font-size="9" fill="#84947b">${i===7?'Сегодня':i<7?'−'+(7-i)+' дн.':'+'+(i-7)+' дн.'}</text>`).join('')}<text x="420" y="32" font-size="9" fill="#889f72">СЦЕНАРНЫЙ ПРОГНОЗ</text></svg>`}
$('#clear').onclick=()=>{selected=null;render()};$('#scenario').onchange=e=>{scenario=e.target.value;render()};$('#forecastMetric').onchange=drawChart;$('#search').oninput=renderTable;$('#layers').querySelectorAll('button').forEach(b=>b.onclick=()=>{layer=b.dataset.layer;$('#layers').querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b));render()});
function exportCSV(){let rows=[['Источник: синтетические демонстрационные данные. Не реальные измерения.'],['Ячейка','Станция','Влажность почвы %','Температура почвы C','Температура воздуха C','Влажность воздуха %','Заряд %','Сценарий'],...data().map(x=>[x.id,x.station,x.moisture,x.temp,x.air,x.humidity,x.battery,scenario])];let url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(x=>x.join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='AgroSfera_demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('48 демонстрационных записей экспортированы')}
