// Extended demo telemetry. No hardware measurements are represented here.
const params={moisture:['Влага почвы','% об.','Почва',1],temp:['Температура почвы','°C','Почва',1],air:['Температура воздуха','°C','Метео',1],humidity:['Влажность воздуха','%','Метео',1],ec:['Электропроводность','мСм/см','Почва',2],solar:['Солнечная радиация','Вт/м²','Метео',0],wind:['Скорость ветра','м/с','Метео',1],rain:['Осадки за час','мм','Метео',1],pressure:['Давление','гПа','Метео',1],battery:['Заряд АКБ','%','Система',1],voltage:['Напряжение АКБ','В','Система',2],vpd:['Дефицит давления пара','кПа','Расчёт',2]};
const round=(n,d=1)=>+n.toFixed(d),endTime=Date.UTC(2026,9,15,12),startTime=endTime-7*86400000;
function sample(i,t,sc=scenario){const b=base[i],hour=new Date(t).getUTCHours()+new Date(t).getUTCMinutes()/60,day=(t-startTime)/86400000,sun=Math.max(0,Math.sin((hour-6)/12*Math.PI)),wave=Math.sin(day*1.7+i*.23),rain=sc==='rain'?(hour>=5&&hour<=8?1.6:0):(day>2&&day<3&&hour<7?.8:0),air=round(14+12*sun+wave+(sc==='dry'?5:sc==='rain'?-3:0)),humidity=round(Math.max(20,Math.min(98,80-30*sun-wave*4+(sc==='rain'?12:0)))),moisture=round(Math.max(5,b.moisture+Math.sin(day)*2-sun*1.4+(sc==='dry'?-7:sc==='rain'?12:0))),temp=round(b.temp+sun*3-2+wave*.5+(sc==='dry'?5:sc==='rain'?-3:0));return {...b,time:new Date(t).toISOString(),moisture,temp,air,humidity,ec:round(.55+moisture*.018+Math.sin(i)*.08,2),solar:round(sun*(680+40*wave),0),wind:round(2.2+1.1*Math.sin(day*3+i*.2)),rain,pressure:round(1014+4*Math.cos(day*.7)),battery:round(Math.min(100,b.battery+sun*3)),voltage:round(12.1+b.battery*.009+sun*.2,2),vpd:round(.6108*Math.exp(17.27*air/(air+237.3))*(1-humidity/100),2)}}
data=()=>base.map((_,i)=>sample(i,endTime));
// Voronoi cells clipped to a single demonstration field boundary.
const boundary=[[85,58],[640,34],[741,112],[710,392],[610,446],[156,430],[48,335],[52,143]];
const seeds=base.map((_,i)=>[110+(i%8)*79+Math.sin(i*2.1)*22,88+Math.floor(i/8)*62+Math.cos(i*1.4)*18]);
function clip(poly,a,b,c){let out=[];for(let i=0;i<poly.length;i++){let p=poly[i],q=poly[(i+1)%poly.length],u=a*p[0]+b*p[1]-c,v=a*q[0]+b*q[1]-c;if(u<=1e-8)out.push(p);if((u<0)!==(v<0)){let f=u/(u-v);out.push([p[0]+f*(q[0]-p[0]),p[1]+f*(q[1]-p[1])])}}return out}
const polygons=seeds.map((p,i)=>seeds.reduce((poly,q,j)=>i===j?poly:clip(poly,2*(q[0]-p[0]),2*(q[1]-p[1]),q[0]**2+q[1]**2-p[0]**2-p[1]**2),boundary));
const area=p=>Math.abs(p.reduce((s,v,i)=>s+v[0]*p[(i+1)%p.length][1]-p[(i+1)%p.length][0]*v[1],0)/2),areas=polygons.map(area),totalArea=areas.reduce((a,b)=>a+b,0);
