let page=0;
function dbKeys(){return [...document.querySelectorAll('#dbParams input:checked')].map(x=>x.value).filter(k=>$('#dbType').value==='all'||params[k][2]===$('#dbType').value)}
function records(all=false){let from=all?startTime:Date.parse($('#dateFrom').value+'Z'),to=all?endTime:Date.parse($('#dateTo').value+'Z');if(!Number.isFinite(from)||!Number.isFinite(to)||from>to||from<startTime||to>endTime)return null;let out=[];for(let t=startTime;t<=endTime;t+=900000)if(t>=from&&t<=to)base.forEach((x,i)=>{if(all||$('#dbCell').value==='all'||$('#dbCell').value===x.id)out.push(sample(i,t))});return out}
