function downloadDB(format,all=false){let rows=records(all),keys=all?Object.keys(params):dbKeys();if(!rows?.length||!keys.length)return toast('Выберите период и хотя бы один параметр');const meta={source:'synthetic_demo_not_measurements',timezone:'UTC',scenario,interval_minutes:15,parameters:Object.fromEntries(keys.map(k=>[k,{label:params[k][0],unit:params[k][1],type:params[k][2]}]))};let content=format==='json'?JSON.stringify({metadata:meta,records:rows.map(r=>Object.fromEntries(['time','id','station',...keys].map(k=>[k,r[k]])))},null,2):'\uFEFF'+[['time_utc','cell','station','source','scenario',...keys.map(k=>`${k} (${params[k][1]})`)].join(';'),...rows.map(r=>[r.time,r.id,r.station,'synthetic_demo',scenario,...keys.map(k=>r[k].toFixed(params[k][3]))].join(';'))].join('\r\n');let a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type:format==='json'?'application/json':'text/csv;charset=utf-8'}));a.href=url;a.download=`AgroSfera_${all?'full':rows[0].time.slice(0,10)}_${scenario}.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast(`${rows.length} строк экспортировано`)}
document.querySelectorAll('.dbfilters input,.dbfilters select,.dbparameters input').forEach(x=>x.onchange=()=>{page=0;renderDB()});$('#selectAll').onclick=()=>{document.querySelectorAll('#dbParams input').forEach(x=>x.checked=true);$('#dbType').value='all';renderDB()};$('#dbPrev').onclick=()=>{page--;renderDB()};$('#dbNext').onclick=()=>{page++;renderDB()};$('#dbCsv').onclick=()=>downloadDB('csv');$('#dbJson').onclick=()=>downloadDB('json');$('#fullExport').onclick=()=>downloadDB('csv',true);$('#export').onclick=()=>switchTab('science');
const historyCache=new Map();
function series(k,count=169){const cacheKey=[selected,scenario,k,count].join('|');if(historyCache.has(cacheKey))return historyCache.get(cacheKey);const index=selected?base.findIndex(x=>x.id===selected):-1;const result=Array.from({length:count},(_,j)=>{let t=endTime-(count-1-j)*3600000;return index>=0?sample(index,t)[k]:base.reduce((s,_,i)=>s+sample(i,t)[k]*areas[i],0)/totalArea});historyCache.set(cacheKey,result);return result}
