const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stateKey='agrosfera-workspace-v6';
const defaults={field:'Опытное поле',crop:'Озимая пшеница',low:22,high:34,hot:26};
let saved={};try{saved=JSON.parse(localStorage.getItem(stateKey)||'{}')||{}}catch{}
let preferences={...defaults,...(saved.settings||{})};
function validSettings(x){return x&&typeof x.field==='string'&&x.field.trim().length>0&&x.field.length<=80&&typeof x.crop==='string'&&x.crop.length<=80&&Number.isFinite(x.low)&&Number.isFinite(x.high)&&x.low>=0&&x.high<=100&&x.low<x.high&&Number.isFinite(x.hot)&&x.hot>=0&&x.hot<=60}
if(!validSettings(preferences))preferences={...defaults};
function validTask(t){return t&&typeof t.id==='string'&&t.id.length<=80&&typeof t.title==='string'&&t.title.trim().length>0&&t.title.length<=120&&typeof t.note==='string'&&t.note.length<=2000&&typeof t.done==='boolean'&&['normal','high'].includes(t.priority)&&base.some(x=>x.id===t.cell)&&/^\d{4}-\d{2}-\d{2}$/.test(t.due)&&Number.isFinite(Date.parse(t.due))}
let tasks=Array.isArray(saved.tasks)?saved.tasks.filter(validTask).slice(0,1000):[];
