if(['normal','dry','rain'].includes(saved.scenario))scenario=saved.scenario;
if(saved.layer==='health'||params[saved.layer])layer=saved.layer;
if(base.some(x=>x.id===saved.selected))selected=saved.selected;
if(stationList.some(x=>x.id===saved.selectedStation))selectedStation=saved.selectedStation;
$('#scenario').value=scenario;
const oldRisk=risk;
risk=x=>x.moisture<preferences.low-6||x.moisture>preferences.high+8||x.temp>preferences.hot+4?2:x.moisture<preferences.low||x.moisture>preferences.high||x.temp>preferences.hot?1:0;
adviceFor=x=>{if(x.moisture<preferences.low)return {title:'Недостаток влаги',reason:`Влажность ${num(x.moisture)}% ниже установленного порога ${preferences.low}%.`,action:'Выполнить контрольный замер и осмотреть растения. Оценить необходимость полива с агрономом.'};if(x.moisture>preferences.high)return {title:'Повышенная влажность',reason:`Влажность ${num(x.moisture)}% выше установленного порога ${preferences.high}%.`,action:'Проверить показания датчика и осмотреть дренаж участка.'};if(x.temp>preferences.hot)return {title:'Нагрев почвы',reason:`Температура ${num(x.temp)} °C выше порога ${preferences.hot} °C.`,action:'Сопоставить показания с погодой и контрольным замером.'};return {title:'Стабильные условия',reason:'Показатели в пределах заданных порогов.',action:'Продолжать наблюдение и плановые осмотры.'}};
const previousDashboardTone=tone;
tone=x=>{if(['health','moisture','temp'].includes(layer)){let r=layer==='health'?risk(x):layer==='temp'?(x.temp>preferences.hot+4?2:x.temp>preferences.hot?1:0):(x.moisture<preferences.low-6||x.moisture>preferences.high+8?2:x.moisture<preferences.low||x.moisture>preferences.high?1:0);return ['#7bbd87','#caa85d','#d47c60'][r]}return previousDashboardTone(x)};
