plots.insertAdjacentHTML('beforeend',`<div class="toolbar"><label>Поиск<input type="search" id="plotSearch" placeholder="Участок или станция…"></label><label>Состояние<select id="plotRisk"><option value="all">Все состояния</option><option value="2">Высокий риск</option><option value="1">Требует внимания</option><option value="0">В норме</option></select></label><label>Станция<select id="plotStation"><option value="all">Все станции</option>${stationList.map(s=>`<option>${s.id}</option>`).join('')}</select></label><label>Сортировка<select id="plotSort"><option value="id">По названию</option><option value="risk">По приоритету</option><option value="moisture">По влажности ↑</option></select></label><span class="result-count" id="plotCount"></span></div><div id="plotCards" class="plots-grid"></div>`);
function renderPlots(){const q=$('#plotSearch').value.toLocaleLowerCase(),r=$('#plotRisk').value,st=$('#plotStation').value,sort=$('#plotSort').value;let d=data().filter(x=>(x.id+' '+x.station).toLocaleLowerCase().includes(q)&&(r==='all'||risk(x)===+r)&&(st==='all'||x.station===st));if(sort==='risk')d.sort((a,b)=>risk(b)-risk(a)||a.id.localeCompare(b.id));if(sort==='moisture')d.sort((a,b)=>a.moisture-b.moisture);$('#plotCount').textContent=`Найдено ${d.length} из 48`;$('#plotCards').innerHTML=d.map(x=>{let r=risk(x),n=tasks.filter(t=>t.cell===x.id&&!t.done).length;return `<article class="panel plot-card"><div class="card-title"><h2>Участок ${x.id}</h2><span class="badge ${['good','watch','risk'][r]}">${['В норме','Внимание','Высокий риск'][r]}</span></div><p class="hint">${x.station} · ${(areas[base.findIndex(b=>b.id===x.id)]/totalArea*48).toFixed(2)} га · ${n} задач</p><div class="plot-values"><div><small>Влажность</small><strong>${num(x.moisture)} %</strong></div><div><small>Почва</small><strong>${num(x.temp)} °C</strong></div></div><div class="card-actions"><button class="primary" data-map="${x.id}">На карте</button><button class="outline" data-data="${x.id}">Измерения</button><button class="outline" data-task="${x.id}">+ Задача</button></div></article>`}).join('')||'<div class="empty">Участки не найдены. Измените поиск или фильтры.</div>';}
