let editingTask=null;const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
function openTask(cell=selected||'A1',id=null){editingTask=id;const t=tasks.find(x=>x.id===id);$('#taskDialogTitle').textContent=t?'Изменить задачу':'Новая задача';$('#taskTitle').value=t?.title||'';$('#taskCell').value=t?.cell||cell;$('#taskDue').value=t?.due||today();$('#taskPriority').value=t?.priority||'normal';$('#taskNote').value=t?.note||'';$('#taskDialog').showModal();$('#taskTitle').focus()}
$('#newTask').onclick=()=>openTask();$('#cancelTask').onclick=()=>$('#taskDialog').close();
$('#taskForm').onsubmit=e=>{e.preventDefault();const title=$('#taskTitle').value.trim();if(!title){$('#taskTitle').setCustomValidity('Введите название задачи');$('#taskTitle').reportValidity();return}const prev=tasks.find(t=>t.id===editingTask);const task={id:prev?.id||(crypto.randomUUID?.()||Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('')),title,cell:$('#taskCell').value,due:$('#taskDue').value,priority:$('#taskPriority').value,note:$('#taskNote').value.trim(),done:prev?.done||false};if(prev)tasks=tasks.map(t=>t.id===prev.id?task:t);else{if(tasks.length>=1000)return toast('Достигнут лимит 1000 задач. Удалите завершённые задачи.');tasks.push(task)}const ok=persist();renderTasks();renderPlots();$('#taskDialog').close();if(ok)toast('Задача сохранена в браузере')};$('#taskTitle').oninput=()=>$('#taskTitle').setCustomValidity('');
function renderTasks(){const filter=$('#taskFilter').value;const filtered=tasks.filter(t=>filter==='all'||(filter==='done'?t.done:!t.done)).sort((a,b)=>a.done-b.done||Number(b.priority==='high')-Number(a.priority==='high')||a.due.localeCompare(b.due));$('#taskCount').textContent=`Открыто: ${tasks.filter(t=>!t.done).length} · завершено: ${tasks.filter(t=>t.done).length}`;$('#taskBadge').textContent=tasks.filter(t=>!t.done).length;$('#taskList').innerHTML=filtered.map(t=>`<article class="panel task-row ${t.done?'completed':''}"><input type="checkbox" class="task-check" data-complete="${escapeHTML(t.id)}" ${t.done?'checked':''} aria-label="Завершить: ${escapeHTML(t.title)}"><div><h3>${escapeHTML(t.title)}</h3><div class="task-meta"><button data-task-map="${t.cell}" class="badge">Участок ${t.cell} ↗</button><small class="${!t.done&&t.due<today()?'overdue':''}">Срок: ${t.due}${!t.done&&t.due<today()?' · просрочена':''}</small><span class="badge ${t.priority==='high'?'risk':''}">${t.priority==='high'?'Высокий':'Обычный'}</span></div>${t.note?`<p>${escapeHTML(t.note)}</p>`:''}</div><button class="outline" data-edit-task="${escapeHTML(t.id)}">Изменить</button><button class="outline" data-delete-task="${escapeHTML(t.id)}" aria-label="Удалить: ${escapeHTML(t.title)}">Удалить</button></article>`).join('')||'<div class="empty">Задач пока нет. Добавьте осмотр участка или контрольный замер.</div>'}
$('#taskFilter').onchange=renderTasks;$('#taskList').onchange=e=>{let t=tasks.find(t=>t.id===e.target.dataset.complete);if(t){t.done=e.target.checked;persist();renderTasks();renderPlots()}};
$('#taskList').onclick=e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.taskMap)openCell(b.dataset.taskMap);if(b.dataset.editTask)openTask(null,b.dataset.editTask);if(b.dataset.deleteTask){let t=tasks.find(t=>t.id===b.dataset.deleteTask);if(confirm(`Удалить задачу «${t.title}»?`)){tasks=tasks.filter(x=>x.id!==t.id);persist();renderTasks();renderPlots()}}};
