settingsPage.insertAdjacentHTML('beforeend',`<div class="settings-grid"><form class="panel form-panel" id="settingsForm"><h2>Поле и пороги</h2><label>Название поля<input id="fieldName" maxlength="80" required></label><label>Культура<input id="crop" maxlength="80"></label><label>Нижняя граница влажности, %<input id="lowThreshold" type="number" min="0" max="99" step="0.1" required></label><label>Верхняя граница влажности, %<input id="highThreshold" type="number" min="1" max="100" step="0.1" required></label><label>Температура внимания, °C<input id="hotThreshold" type="number" min="0" max="60" step="0.1" required></label><p>Пороги изменяют цвета карты и рекомендации. Высокий риск: влага ниже нижней границы на 6 п.п. или выше верхней на 8 п.п.; температура выше порога на 4 °C.</p><p class="error" id="settingsError" role="alert"></p><button class="primary">Сохранить настройки</button></form><div class="panel form-panel"><h2>Ваши данные</h2><p>Задачи, настройки, выбранный участок и сценарий сохраняются локально в этом браузере. Для переноса на другой компьютер скачайте резервную копию.</p><button class="outline" id="backup">Скачать резервную копию</button><label>Восстановить из JSON<input type="file" id="restore" accept="application/json,.json"></label><p>Импорт заменяет задачи и настройки после подтверждения. Принимаются резервные копии АгроСферы версии 1.</p><p class="error" id="restoreStatus" role="status"></p><h2 style="margin-top:28px">О данных</h2><p>Срез телеметрии: 15.10.2026, 12:00 UTC. История: 7 дней. Смена сценария пересчитывает карту, графики и экспорт. Лабораторные пробы сохраняют дату 08.10.2026.</p><p>Настоящие датчики и серверная синхронизация не подключены. Пороговые рекомендации — учебные правила, а не обученная модель.</p><button class="outline" id="resetThresholds">Вернуть стандартные пороги</button></div></div>`);
function loadSettings(){ $('#fieldName').value=preferences.field;$('#crop').value=preferences.crop;$('#lowThreshold').value=preferences.low;$('#highThreshold').value=preferences.high;$('#hotThreshold').value=preferences.hot;$('#farmName').textContent=preferences.field;$('#cropName').textContent=preferences.crop+' · демонстрационное поле';}
$('#settingsForm').onsubmit=e=>{e.preventDefault();const next={field:$('#fieldName').value.trim(),crop:$('#crop').value.trim(),low:+$('#lowThreshold').value,high:+$('#highThreshold').value,hot:+$('#hotThreshold').value};if(!validSettings(next)){$('#settingsError').textContent='Укажите название и корректные пороги. Нижняя влажность должна быть меньше верхней.';return}preferences=next;$('#settingsError').textContent='';loadSettings();render();if(persist())toast('Настройки сохранены')};
