$('#restore').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>3000000)throw Error('Файл больше 3 МБ.');const x=JSON.parse(await file.text());if(x.app!=='AgroSfera'||x.version!==1||!validSettings(x.settings)||!Array.isArray(x.tasks)||x.tasks.length>1000||!x.tasks.every(validTask)||new Set(x.tasks.map(t=>t.id)).size!==x.tasks.length)throw Error('Файл не соответствует формату резервной копии.');if(!confirm(`Заменить настройки и текущие ${tasks.length} задач данными из файла (${x.tasks.length} задач)?`))return;preferences=x.settings;tasks=x.tasks;loadSettings();render();renderTasks();if(persist())$('#restoreStatus').textContent='Данные восстановлены.';}catch(err){$('#restoreStatus').textContent='Не удалось восстановить: '+err.message}finally{e.target.value=''}};
function renderDashboard(){const c=current(),soil=selected?soilSample(base.findIndex(x=>x.id===selected)).ph:base.reduce((s,_,i)=>s+soilSample(i).ph*areas[i],0)/totalArea;$('#dashboardKpis').innerHTML=[['Влажность почвы',c.moisture,'%','Телеметрия · демо'],['Температура почвы',c.temp,'°C','Телеметрия · демо'],['Кислотность',soil,'pH','Лабораторная проба · 08.10'],['Проводимость',c.ec,'мСм/см','Телеметрия · демо']].map(([label,value,unit,source])=>`<article class="metric"><span>${label}</span><strong>${num(value)} <em>${unit}</em></strong><small>${source}</small></article>`).join('');$('#analysisSelection').textContent=selected?'Выбран участок '+selected:'Среднее по полю';$('#dbScenario').value=scenario;$('#mapMetric').value=layer;$('#metricTitle').textContent=selected?'Все показатели · '+selected:'Все показатели поля';$('#maptitle').textContent=selected?'Карта участков · '+selected:'Карта участков';renderPlots();}
