let mapZoom=1;const setMapZoom=()=>{$('#grid').style.transform=`scale(${mapZoom})`;$('#grid').style.transformOrigin='50% 50%';$('#zoomOut').disabled=mapZoom<=1;$('#zoomIn').disabled=mapZoom>=2};$('#zoomIn').onclick=()=>{mapZoom=Math.min(2,mapZoom+.25);setMapZoom()};$('#zoomOut').onclick=()=>{mapZoom=Math.max(1,mapZoom-.25);setMapZoom()};$('#zoomReset').onclick=()=>{mapZoom=1;setMapZoom()};
