const conceptTone=tone;tone=x=>{if(layer==='moisture'){const f=Math.max(0,Math.min(1,(x.moisture-5)/40));return `hsl(${215-Math.pow(1-f,3)*170} 80% ${52-f*15}%)`}if(layer==='temp'){const f=Math.max(0,Math.min(1,(x.temp-10)/30));return `hsl(${210-f*175} 82% 52%)`}return conceptTone(x)};
function conceptMap(){const key=labLayers.includes(conceptLayer)?conceptLayer:layer;if(labLayers.includes(key)){const spec=soilFields[key],vals=base.map((_,i)=>soilSample(i)[key]),min=Math.min(...vals),max=Math.max(...vals);$('#grid').querySelectorAll('g[data-id]').forEach((g,i)=>{const value=vals[i],f=(value-min)/(max-min||1);g.querySelector('polygon').style.setProperty('--cell-color',`hsl(${45+170*f} 78% 46%)`);g.querySelector('text.cellvalue').textContent=value.toFixed(spec[2]);g.querySelector('title').textContent=`${base[i].id} · ${spec[0]}: ${value} ${spec[1]} · проба 08.10.2026`});$('.maplegend').innerHTML=`<strong>${spec[0]} · лаборатория, демо</strong><span class="heat-ramp"></span><span class="legend-range">${min.toFixed(1)}<span>${max.toFixed(1)} ${spec[1]}</span></span>`}else if(['moisture','temp'].includes(layer)){const vals=data().map(x=>x[layer]);$('.maplegend').innerHTML=`<strong>${params[layer][0]}, ${params[layer][1]} · демо</strong><span class="heat-ramp ${layer==='temp'?'temperature':''}"></span><span class="legend-range">${layer==='temp'?'10':'5'}<span>${layer==='temp'?'40 °C':'45 %'}</span></span>`}document.querySelectorAll('[data-concept-layer]').forEach(b=>b.classList.toggle('selected',b.dataset.conceptLayer===key));setMapZoom()}
$('#layers').onclick=e=>{const b=e.target.closest('[data-concept-layer]');if(!b)return;conceptLayer=b.dataset.conceptLayer;layer=labLayers.includes(conceptLayer)?'health':conceptLayer;render();persist()};$('#mapMetric').onchange=e=>{layer=e.target.value;conceptLayer=layer;render();persist()};
const miniLine=(values,color)=>{const lo=Math.min(...values),hi=Math.max(...values),p=values.map((v,i)=>`${i?'L':'M'}${i*150/(values.length-1)},${53-(v-lo)/(hi-lo||1)*40}`).join(' ');return `<svg viewBox="0 0 155 65" role="img" aria-label="Динамика демонстрационных значений"><path d="M0 10H155M0 32H155M0 54H155M0 5V60M38 5V60M76 5V60M114 5V60M154 5V60" stroke="var(--line)" fill="none"/><path d="${p}" fill="none" stroke="${color}" stroke-width="2"/></svg>`};
function soilCurrent(k){return selected?soilSample(base.findIndex(x=>x.id===selected))[k]:base.reduce((s,_,i)=>s+soilSample(i)[k]*areas[i],0)/totalArea}
